function anomExportExcel(){
  const rows=anomFilteredForTable();
  if(!rows.length){ alert('Tidak ada data untuk diekspor.'); return; }
  if(typeof XLSX==='undefined'){ alert('Library Excel belum siap, coba lagi sebentar.'); return; }
  const head=['Jenis','No Anomali','Nama','Keterangan Anomali','Kecamatan','Desa','Kode SLS','Email Petugas','Status','Link FASIH'];
  const data=[head].concat(rows.map(r=>[
    r.jenis, r.anomali_no, r.nama,
    (()=>{ const m=(r.anomali||'').match(/\\(([^)]+)\\)/); return m?'('+m[1]+')':r.anomali||''; })(),
    r.kecamatan, r.desa, String(r.kode_wilayah||'').slice(10,14), r.email||'',
    r.is_resolved?'Sudah':'Belum', r.link_fasih||''
  ]));
  const ws=XLSX.utils.aoa_to_sheet(data);
  ws['!cols']=[{wch:10},{wch:8},{wch:28},{wch:40},{wch:14},{wch:16},{wch:18},{wch:28},{wch:8},{wch:60}];
  const wb=XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb,ws,'Anomali');
  XLSX.writeFile(wb,'anomali_terfilter.xlsx');
}

function esc(s){ return String(s==null?'':s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])); }
function setTxt(id,v){ const e=document.getElementById(id); if(e) e.textContent=(v==null?'–':v); }
function shorten(s){ s=String(s||''); return s.length>26? s.slice(0,24)+'…' : s; }

