const C = { open:'#3b82f6', draft:'#a855f7', submit:'#f59e0b', reject:'#ef4444', approve:'#10b981' };
const STAT = ['open','draft','submit','reject','approve'];

function pctColor(p){ if(p>=75)return '#10b981'; if(p>=50)return '#3b82f6'; if(p>=25)return '#f59e0b'; return '#ef4444'; }
function progDoc(o){ return o.submit + o.reject + o.approve; }
function fmt(n){ return (Math.round(n)||0).toLocaleString('id-ID'); }
function pacePerHari(sisaDok, sisaHari){
    return Math.max(1, Math.ceil((sisaDok||0) / (sisaHari||1)));
}
function localYmd(d){
    return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function sisaHariMenujuDeadline(dateStr){
    const start=new Date((dateStr||localYmd(new Date()))+'T00:00:00');
    const end=new Date('2026-08-15T23:59:59');
    return Math.max(1, Math.ceil((end-start)/(1000*60*60*24)));
}
function paceTargetHarian(sisaDok, dateStr){
    return pacePerHari(sisaDok, sisaHariMenujuDeadline(dateStr));
}


function normalizeKorwilPml(){
    // Struktur: 1 korwil = 1 PML. Samakan PML tiap baris ke PML DOMINAN korwilnya,
    // agar total progres/target korwil == total PML-nya (perbaiki atribusi PPL yg keliru).
    function fix(arr){
        if(!Array.isArray(arr)) return;
        const cnt={};
        arr.forEach(r=>{ if(r.korwil&&r.pml){ (cnt[r.korwil]=cnt[r.korwil]||{}); cnt[r.korwil][r.pml]=(cnt[r.korwil][r.pml]||0)+1; } });
        const canon={};
        for(const k in cnt){ let best=null,bn=-1; for(const p in cnt[k]){ if(cnt[k][p]>bn){bn=cnt[k][p];best=p;} } canon[k]=best; }
        arr.forEach(r=>{ if(r.korwil&&canon[r.korwil]) r.pml=canon[r.korwil]; });
    }
    fix(typeof rawData!=='undefined'?rawData:null);
    fix(typeof rawDesa!=='undefined'?rawDesa:null);
}
function initDashboard(){ normalizeKorwilPml(); buildHistory(); populateFilterOptions(); applyFilters(); renderTrend(); }

// ===================== DIMENSI WAKTU: hitung snapshot hari ini + gabung riwayat =====================
function todaySnapshot(){
    // agregat dari rawData (data hari ini): total + per korwil/kec/pml/ppl.
    // PENTING: disamakan dgn todaySnap() versi builder (Node) agar snapshot "hari ini" yang
    // ditambahkan otomatis saat dashboard dibuka di browser TETAP punya breakdown per-PPL & per-PML —
    // tanpa ini, grafik tren harian per-PPL akan "macet" di tanggal terakhir kali file di-generate ulang
    // dari FASIH, karena renderPplTrend() membuang entri MERGED_HISTORY yang tidak punya field .ppl.
    let T={open:0,draft:0,submit:0,reject:0,approve:0};
    const kor={}, kec={}, pml={}, pplAcc={};
    rawData.forEach(r=>{ ['open','draft','submit','reject','approve'].forEach(s=>T[s]+=r[s]);
        const tt=r.total, pg=r.submit+r.reject+r.approve;
        if(r.korwil){kor[r.korwil]=kor[r.korwil]||{t:0,p:0};kor[r.korwil].t+=tt;kor[r.korwil].p+=pg;}
        if(r.kec){kec[r.kec]=kec[r.kec]||{t:0,p:0};kec[r.kec].t+=tt;kec[r.kec].p+=pg;}
        if(r.pml){pml[r.pml]=pml[r.pml]||{t:0,p:0};pml[r.pml].t+=tt;pml[r.pml].p+=pg;}
        if(r.ppl){pplAcc[r.ppl]=pplAcc[r.ppl]||{t:0,p:0};pplAcc[r.ppl].t+=tt;pplAcc[r.ppl].p+=pg;}
    });
    const total=T.open+T.draft+T.submit+T.reject+T.approve;
    const pct= total>0? (T.submit+T.reject+T.approve)/total*100 : 0;
    const pctOf=o=>Object.fromEntries(Object.entries(o).map(([k,v])=>[k, v.t>0?+(v.p/v.t*100).toFixed(1):0]));
    const dokOf=o=>Object.fromEntries(Object.entries(o).map(([k,v])=>[k, v.p]));  // jumlah dokumen selesai (kumulatif) per scope
    // tanggal hari ini (lokal). Di preview pakai env date; di FASIH skrip yg set.
    const d=new Date(); const ymd=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
    return {date:ymd, total, ...T, pct:+pct.toFixed(2), korwil:pctOf(kor), kec:pctOf(kec), pml:pctOf(pml), ppl:pctOf(pplAcc),
        dok:{ total:(T.submit+T.reject+T.approve), korwil:dokOf(kor), kec:dokOf(kec), pml:dokOf(pml), ppl:dokOf(pplAcc) }};
}
function buildHistory(){
    const byDate={};
    (HISTORY||[]).forEach(h=>{ byDate[h.date]=h; });
    // PREVIEW (simulasi): pakai HISTORY apa adanya (sudah berisi 'hari ini' simulasi).
    // VERSI FASIH (HISTORY_SIMULATED=false): tambahkan snapshot live hari ini (timpa tanggal sama).
    const sim = (typeof HISTORY_SIMULATED!=='undefined' && HISTORY_SIMULATED);
    if(!sim){ const today=todaySnapshot(); byDate[today.date]=today; }
    MERGED_HISTORY=Object.values(byDate).sort((a,b)=>a.date.localeCompare(b.date));
    const badge=document.getElementById('hist-sim-badge');
    if(badge && sim) badge.classList.remove('hidden');
}
// Interpolasi target linear antar milestone -> persen target pd tanggal d (YYYY-MM-DD)
function targetAt(dateStr){
    const ms=Object.entries(TARGET).map(([d,p])=>[Date.parse(d),p]).sort((a,b)=>a[0]-b[0]);
    if(ms.length===0) return null;
    const t=Date.parse(dateStr);
    if(t<=ms[0][0]) return ms[0][1];
    if(t>=ms[ms.length-1][0]) return ms[ms.length-1][1];
    for(let i=0;i<ms.length-1;i++){ if(t>=ms[i][0]&&t<=ms[i+1][0]){
        const f=(t-ms[i][0])/(ms[i+1][0]-ms[i][0]); return ms[i][1]+(ms[i+1][1]-ms[i][1])*f; } }
    return null;
}

function populateFilterOptions(){
    const k=new Set(), p=new Set(), kc=new Set();
    rawData.forEach(i=>{ if(i.korwil)k.add(i.korwil); if(i.pml)p.add(i.pml); if(i.kec)kc.add(i.kec); });
    updateDropdown('filter-korwil',k); updateDropdown('filter-pml',p); updateDropdown('filter-kecamatan',kc);
}
function updateDropdown(id,set){
    const s=document.getElementById(id); s.innerHTML=s.options[0].outerHTML;
    Array.from(set).sort().forEach(v=>{ const o=document.createElement('option'); o.value=v; o.innerText=v; s.appendChild(o); });
}

// SINGLE-SELECT: hanya satu filter boleh aktif. Memilih satu mereset lainnya.
