var __DESACMP_KATS_ALL = ["A","B","C","D","E","F","G","H","I","J","K","L","M","N_O","P","Q","R","S_U"];

function __buildSt2023ByDesa(){
  var byDesa = {};
  Object.keys(__ST2023_RAW).forEach(function(code){
    var v = __ST2023_RAW[code];
    var dkey = code.slice(0,10);
    if(!(dkey in byDesa)) byDesa[dkey]=0;
    if(v!=null && !isNaN(v)) byDesa[dkey]+=Number(v);
  });
  var m={};
  Object.keys(byDesa).forEach(function(k){ m[k] = byDesa[k]===0 ? null : byDesa[k]; });
  return m;
}

function buildDesaCmpModel(){
  var usahaWebByKode14 = {};
  (window.__USAHA_WEB_SE || []).forEach(function(r){
    var g=usahaWebByKode14[r.kode14]||(usahaWebByKode14[r.kode14]={pertanian:0,nonpertanian:0});
    g.pertanian+=parseInt(r.pertanian,10)||0; g.nonpertanian+=parseInt(r.nonpertanian,10)||0;
  });
  var st2023ByDesa = __buildSt2023ByDesa();
  var byDesa = {};
  (window.__SLS_MASTER || []).forEach(function(m){
    var dkey = String(m.kode14).slice(0,10);
    var g = byDesa[dkey] || (byDesa[dkey] = {kodeDesa:dkey, kec:m.kec, desa:m.desa, pertanian:0, nonpertanian:0});
    var kr = usahaWebByKode14[m.kode14] || {};
    g.pertanian += parseInt(kr.pertanian, 10) || 0;
    g.nonpertanian += parseInt(kr.nonpertanian, 10) || 0;
  });
  return Object.keys(byDesa).map(function(k){
    var g = byDesa[k];
    var sbr = SBR_AKTIF_BY_DESA[k];
    var hasSbr = sbr !== undefined;
    var st2023 = st2023ByDesa[k];
    var hasSt = st2023!==undefined && st2023!==null;
    return {
      kodeDesa:k, kec:g.kec, desa:g.desa,
      pertanian:g.pertanian, nonpertanian:g.nonpertanian,
      st2023: hasSt ? st2023 : null,
      sbr: hasSbr ? sbr : null,
      selst: hasSt ? (g.pertanian - st2023) : null,
      selsbr: hasSbr ? (g.nonpertanian - sbr) : null
    };
  });
}

(function(){
  var DESACMP_SORT = {key:'kec', dir:1};
  function fmtN(n){ return n==null ? '-' : Number(n).toLocaleString('id-ID'); }
  function escD(s){ return (s==null?'':String(s)).replace(/[&<>]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]||c;}); }
  function selClass(v){ return v==null ? 'text-slate-300' : (v<0 ? 'text-rose-600 font-semibold' : 'text-emerald-700'); }
  window.renderDesaCmp = function(){
    var rows = buildDesaCmpModel();
    var sumPertanian = rows.reduce(function(a,r){ return a+(r.pertanian||0); }, 0);
    var sumNonpertanian = rows.reduce(function(a,r){ return a+(r.nonpertanian||0); }, 0);
    var sumSt2023 = rows.reduce(function(a,r){ return a+(r.st2023||0); }, 0);
    var sumSbr = rows.reduce(function(a,r){ return a+(r.sbr||0); }, 0);
    var kP=document.getElementById('desacmp-kpi-pertanian'); if(kP) kP.textContent = fmtN(sumPertanian);
    var kN=document.getElementById('desacmp-kpi-nonpertanian'); if(kN) kN.textContent = fmtN(sumNonpertanian);
    var kS=document.getElementById('desacmp-kpi-st2023'); if(kS) kS.textContent = fmtN(sumSt2023);
    var kB=document.getElementById('desacmp-kpi-sbr'); if(kB) kB.textContent = fmtN(sumSbr);
    var key=DESACMP_SORT.key, dir=DESACMP_SORT.dir;
    rows.sort(function(a,b){
      var av=a[key], bv=b[key];
      if(typeof av==='string'||typeof bv==='string') return dir*String(av||'').localeCompare(String(bv||''));
      av = (av==null?-Infinity:av); bv=(bv==null?-Infinity:bv);
      return dir*(av-bv);
    });
    document.getElementById('desacmp-count').textContent = rows.length;
    var tb=document.getElementById('desacmp-tbody');
    tb.innerHTML = rows.map(function(r){
      return '<tr class="border-t border-slate-100 hover:bg-slate-50">'
        +'<td class="px-2 py-1.5">'+escD(r.kec)+'</td>'
        +'<td class="px-2 py-1.5">'+escD(r.desa)+'</td>'
        +'<td class="px-1 py-1.5 text-center">'+fmtN(r.pertanian)+'</td>'
        +'<td class="px-1 py-1.5 text-center">'+fmtN(r.st2023)+'</td>'
        +'<td class="px-1 py-1.5 text-center '+selClass(r.selst)+'">'+fmtN(r.selst)+'</td>'
        +'<td class="px-1 py-1.5 text-center">'+fmtN(r.nonpertanian)+'</td>'
        +'<td class="px-1 py-1.5 text-center">'+fmtN(r.sbr)+'</td>'
        +'<td class="px-1 py-1.5 text-center '+selClass(r.selsbr)+'">'+fmtN(r.selsbr)+'</td>'
        +'</tr>';
    }).join('') || '<tr><td colspan="8" class="text-center py-6 text-slate-300">-</td></tr>';
  };
  document.addEventListener('DOMContentLoaded', function(){
    var ths = document.querySelectorAll('#desacmp-table th[data-sort]');
    ths.forEach(function(th){
      th.addEventListener('click', function(){
        var k = th.getAttribute('data-sort');
        if(DESACMP_SORT.key===k) DESACMP_SORT.dir *= -1; else { DESACMP_SORT.key=k; DESACMP_SORT.dir=1; }
        if(!document.getElementById('desacmp-panel').hidden) window.renderDesaCmp();
      });
    });
    function toggleDesaFS(){
      var el = document.getElementById('desacmp-fs'); if(!el) return;
      if(!document.fullscreenElement){ if(el.requestFullscreen) el.requestFullscreen(); }
      else { if(document.exitFullscreen) document.exitFullscreen(); }
    }
    function onDesaFSchange(){
      var sc=document.getElementById('desacmp-scroll'); var el=document.getElementById('desacmp-fs');
      var isFS=!!document.fullscreenElement;
      if(sc) sc.style.maxHeight = isFS ? '88vh' : '720px';
      if(el){ el.style.background = isFS ? '#fff' : ''; el.style.padding = isFS ? '12px' : ''; el.style.overflow = isFS ? 'auto' : ''; }
      var b=document.getElementById('desacmp-fullscreen'); if(b) b.textContent = isFS ? '⛶ Keluar layar penuh' : '⛶ Layar penuh';
    }
    var fsBtn = document.getElementById('desacmp-fullscreen');
    if(fsBtn) fsBtn.addEventListener('click', toggleDesaFS);
    document.addEventListener('fullscreenchange', onDesaFSchange);
    var xlsBtn = document.getElementById('desacmp-xls');
    if(xlsBtn) xlsBtn.addEventListener('click', function(){
      var rows = buildDesaCmpModel();
      rows.sort(function(a,b){ return String(a.kec).localeCompare(String(b.kec)) || String(a.desa).localeCompare(String(b.desa)); });
      var head=["Kecamatan","Desa","SE2026 Pertanian","Usaha ST2023","Selisih vs ST2023","SE2026 Non-Pertanian","Usaha SBR (Aktif)","Selisih vs SBR"];
      var t='<table border="1"><tr>';
      for(var i=0;i<head.length;i++) t+='<th>'+escD(head[i])+'</th>'; t+='</tr>';
      for(var j=0;j<rows.length;j++){ var r=rows[j];
        var stBg = r.selst==null?'':(r.selst<0?' style="background:#fee2e2;color:#b91c1c"':' style="background:#dcfce7;color:#15803d"');
        var sbrBg = r.selsbr==null?'':(r.selsbr<0?' style="background:#fee2e2;color:#b91c1c"':' style="background:#dcfce7;color:#15803d"');
        t+='<tr><td>'+escD(r.kec)+'</td><td>'+escD(r.desa)+'</td><td>'+r.pertanian
          +'</td><td>'+(r.st2023==null?'':r.st2023)+'</td><td'+stBg+'>'+(r.selst==null?'':r.selst)
          +'</td><td>'+r.nonpertanian+'</td><td>'+(r.sbr==null?'':r.sbr)+'</td><td'+sbrBg+'>'+(r.selsbr==null?'':r.selsbr)
          +'</td></tr>';
      }
      t+='</table>';
      var html='<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="utf-8"></head><body>'+t+'</body></html>';
      var blob=new Blob(['﻿'+html],{type:'application/vnd.ms-excel'});
      var a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='perbandingan_se2026_per_desa_lembata.xls';
      document.body.appendChild(a); a.click(); a.remove();
    });
  });
})();

