    var totalPages=Math.max(1, Math.ceil(sorted.length/pageSize));
    if(pageIdx>=totalPages) pageIdx=totalPages-1; if(pageIdx<0) pageIdx=0;
    var pageRows=sorted.slice(pageIdx*pageSize, (pageIdx+1)*pageSize);
