  const REQUEST_GAP_MS=3500;
  let nextRequestAt=0, globalCooldownUntil=0;
  const wait=ms=>new Promise(r=>setTimeout(r,ms));
  async function waitRequestSlot(){
    const now=Date.now();
    const slot=Math.max(now,nextRequestAt,globalCooldownUntil);
    nextRequestAt=slot+REQUEST_GAP_MS;
    if(slot>now) await wait(slot-now);
  }
  function retryDelay(res,attempt){
    const raw=res.headers.get('Retry-After');
    let fromHeader=0;
    if(raw){
      const seconds=Number(raw);
      fromHeader=Number.isFinite(seconds) ? seconds*1000 : Math.max(0,Date.parse(raw)-Date.now());
    }
    const exponential=Math.min(120000,65000*Math.pow(2,attempt-1));
    return Math.max(fromHeader,exponential)+Math.floor(Math.random()*3000);
  }
  async function fetchPetugas(email,page=0,size=10){
    const body={surveyPeriodId:SURVEY_PERIOD_ID,page,size,search:email,regionSummaryLevel:6,surveyRoleId:ROLE_ID,target:"TARGET_ONLY",region:{region1Id:null,region2Id:null,region3Id:null,region4Id:null,region5Id:null,region6Id:null}};
    for(let attempt=1;attempt<=3;attempt++){
      await waitRequestSlot();
      const ac=new AbortController(); const to=setTimeout(()=>ac.abort(),20000);
      try{ const res=await fetch(BASE,{method:"POST",credentials:"include",signal:ac.signal,headers:{"Content-Type":"application/json","X-XSRF-TOKEN":xsrf,"Accept":"application/json"},body:JSON.stringify(body)});
        clearTimeout(to);
        if(res.status===401||res.status===403){ throw new Error("Sesi habis "+res.status); }
        if(res.status===429){
          throw new Error("HTTP 429: kuota FASIH belum pulih");
        }
        if(!res.ok){
          if(res.status>=500&&attempt<3){ await wait(Math.min(15000,1500*attempt)); continue; }
          const detail=(await res.text()).replace(/\s+/g,' ').trim().slice(0,300);
          throw new Error("HTTP "+res.status+(detail?": "+detail:""));
        }
        const raw=await res.text();
        const trimmed=raw.trim();
        if(trimmed.startsWith('<')){
          if(/login|keycloak|sign[ -]?in|session expired/i.test(trimmed)) throw new Error("Sesi habis (FASIH mengirim halaman login)");
          throw new Error(`Respons HTML untuk ${email}; sesi atau layanan FASIH tidak siap`);
        }
        let j;
        try{ j=JSON.parse(raw); }
        catch(_){
          throw new Error(`Respons bukan JSON untuk ${email}`);
        }
        const data=j.data||{};
        return {content:data.content||[],totalPages:Number(data.totalPages||0),totalElements:Number(data.totalElements||0),last:data.last};
      }catch(e){
        clearTimeout(to);
        if(String(e.message).indexOf("Sesi habis")>=0) throw e;
        if(/^HTTP 4\d\d/.test(String(e.message))) throw e;
        if(attempt===3) throw new Error(`${email}: ${e.message}`);
        await wait(Math.min(15000,1200*attempt));
      }
    }
    throw new Error(`${email}: gagal setelah 3 percobaan singkat`);
  }
  const CKPT_DB='se2026_progress_checkpoint_v10', CKPT_STORE='state', CKPT_KEY='lembata';
  function openCheckpointDb(){
    return new Promise((resolve,reject)=>{const req=indexedDB.open(CKPT_DB,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(CKPT_STORE))req.result.createObjectStore(CKPT_STORE);};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
  }
  async function readCheckpoint(){const db=await openCheckpointDb();try{return await new Promise((resolve,reject)=>{const req=db.transaction(CKPT_STORE,'readonly').objectStore(CKPT_STORE).get(CKPT_KEY);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error);});}finally{db.close();}}
  async function writeCheckpoint(value){const db=await openCheckpointDb();try{await new Promise((resolve,reject)=>{const tx=db.transaction(CKPT_STORE,'readwrite');tx.objectStore(CKPT_STORE).put(value,CKPT_KEY);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}finally{db.close();}}
  async function clearCheckpoint(){const db=await openCheckpointDb();try{await new Promise((resolve,reject)=>{const tx=db.transaction(CKPT_STORE,'readwrite');tx.objectStore(CKPT_STORE).delete(CKPT_KEY);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}finally{db.close();}}
  window.hapusCheckpointProgres=async()=>{await clearCheckpoint();console.log('Checkpoint progres v10 dihapus.');};
  async function tarikSemuaPetugas(){
    const BATCH_SIZE=50;
    const signature=EMAILS_PROG.map(e=>String(e).toLowerCase()).join('|');
    let ckpt=await readCheckpoint();
    if(!ckpt||ckpt.signature!==signature)ckpt={signature,nextIndex:0,officers:[]};
    const out=Array.isArray(ckpt.officers)?ckpt.officers:[];
    const seen=new Set(out.map(pt=>pt.userId||pt.email||pt.username).filter(Boolean));
    let idx=Math.max(0,Math.min(Number(ckpt.nextIndex)||0,EMAILS_PROG.length));
    const end=Math.min(idx+BATCH_SIZE,EMAILS_PROG.length);
    console.log(`  Checkpoint v10: mulai ${idx+1}, batch sampai ${end}/${EMAILS_PROG.length}.`);
    while(idx<end){
      const email=EMAILS_PROG[idx];
      let list;
      try{list=(await fetchPetugas(email)).content;}
      catch(err){
        await writeCheckpoint({signature,nextIndex:idx,officers:out,updatedAt:new Date().toISOString()});
        throw new Error(`${err.message}. Checkpoint tersimpan di ${idx}/${EMAILS_PROG.length}; jalankan ulang setelah login/kuota pulih.`);
      }
      list.forEach(pt=>{const k=pt.userId||pt.email||pt.username;if(k!=null){if(seen.has(k))return;seen.add(k);}out.push(pt);});
      idx++;
      await writeCheckpoint({signature,nextIndex:idx,officers:out,updatedAt:new Date().toISOString()});
      if(idx%10===0||idx===end)console.log(`  tarik progres: ${idx}/${EMAILS_PROG.length} email; ${out.length} petugas unik tersimpan.`);
    }
    if(idx<EMAILS_PROG.length){
      console.warn(`BATCH SELESAI: checkpoint ${idx}/${EMAILS_PROG.length}. Tunggu kuota pulih/login ulang, lalu jalankan v10 lagi.`);
      return {complete:false,officers:[]};
    }
    await clearCheckpoint();
    console.log(`SEMUA BATCH LENGKAP: ${EMAILS_PROG.length}/${EMAILS_PROG.length}. Checkpoint dibersihkan.`);
    return {complete:true,officers:out};
  }
