  const STAT=['open','draft','submit','reject','approve'];
  function parseStatus(sb){const o={open:0,draft:0,submit:0,reject:0,approve:0};(sb||[]).forEach(s=>{const st=s.status||"";if(st.includes("APPROVED")||st.includes("COMPLETED"))o.approve+=s.count;else if((st.includes("SUBMITTED")&&!st.includes("RESPONDENT"))||st.includes("EDITED"))o.submit+=s.count;else if(st.includes("DRAFT"))o.draft+=s.count;else if(st.includes("REJECTED")||st.includes("REVOKED"))o.reject+=s.count;else if(st==="OPEN")o.open+=s.count;});return o;}

  const slsProg={};const desaOnlyProg={};let matchedSls=0,unmatched=0;
